resource "aws_s3_bucket" "files" {
  bucket        = "${var.project}-files-${var.environment}"
  force_destroy = var.force_destroy


  tags = merge(local.common_tags, {
    Service = "file-service"
  })
}

resource "aws_s3_bucket" "data_lake" {
  bucket        = "${var.project}-data-lake-${var.environment}"
  force_destroy = var.force_destroy


  tags = merge(local.common_tags, {
    Service = "analytics-service"
  })
}

resource "aws_s3_bucket" "audit_archive" {
  bucket        = "${var.project}-audit-archive-${var.environment}"
  force_destroy = var.force_destroy


  tags = merge(local.common_tags, {
    Service = "audit-service"
  })
}

resource "aws_s3_bucket_lifecycle_configuration" "audit_archive" {
  bucket = aws_s3_bucket.audit_archive.id

  rule {
    id     = "expire-noncurrent-versions"
    status = "Enabled"
    filter {}
    noncurrent_version_expiration {
      noncurrent_days = 365
    }
    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }

  depends_on = [aws_s3_bucket_versioning.audit_archive]
}

